SELECT "REGION", SUM("NAME") FROM (SELECT LAKEHOUSE_SCAN('{"table_root":"s3://warehouse/db/events","projection":["REGION","NAME"],"emit_exa_types":["VARCHAR(2000000)","VARCHAR(2000000)"],"storage":{"connection":{"name":"LAKEHOUSE_CATALOG_CREDS","allow_http":true}},"df_target_partitions":4,"df_batch_size":8192,"df_threads_per_udf":2,"memory_pool_fraction":0.6,"instance_overhead_mb":200,"s3_max_connections":8}', files) EMITS ("REGION" VARCHAR(2000000), "NAME" VARCHAR(2000000)) FROM (SELECT LAKEHOUSE_DISTRIBUTE_FILES(files) FROM (VALUES (0,'[["data/part-0.parquet",1000]]'),(1,'[["data/part-1.parquet",2000]]'),(2,'[["data/part-2.parquet",1500]]')) AS shards(shard_key, files) GROUP BY shard_key)) AS "LHS_T0" GROUP BY "REGION"